head.script:
{
  "@context": "https://schema.org",
  "@type": "Service",
  "name": "تفصيل مرايا الرياض",
  "description": "نقدم تفصيل وتركيب مرايا في الرياض للحمامات، المغاسل، الصالات، الجدران، غرف الملابس، والمشاريع التجارية.",
  "provider": {
    "@type": "LocalBusiness",
    "name": "زجاج الرياض برو",
    "telephone": "+966578787396",
    "url": "https://riyadh-glass.vercel.app"
  },
  "areaServed": {
    "@type": "City",
    "name": "الرياض"
  },
  "serviceType": "مرايا تفصيل الرياض",
  "url": "https://riyadh-glass.vercel.app/services/custom-mirrors-riyadh"
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "كم سعر تفصيل مرايا الرياض؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "السعر يعتمد على المقاس، نوع الخامة، مكان التركيب، وعدد القطع. أرسل الصور والمقاسات للحصول على تقدير أدق."
      }
    },
    {
      "@type": "Question",
      "name": "هل الخدمة متاحة في كل الرياض؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "الخدمة تستهدف أغلب مناطق الرياض حسب توفر المواعيد ونطاق العمل."
      }
    },
    {
      "@type": "Question",
      "name": "ماذا أرسل للحصول على عرض سعر؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "أرسل صورة المكان، المقاسات التقريبية، نوع الخدمة، والحي عبر واتساب."
      }
    }
  ]
}
